/**
 * Hub environment: bindings (generated by `wrangler types` into worker-configuration.d.ts),
 * secrets (declared here — they are not in wrangler.jsonc) and the parsed, typed config.
 */

/** Secrets set with `wrangler secret put` (or `.dev.vars` locally). All optional: dev runs without. */
export interface HubSecrets {
  /** GitHub App numeric id. */
  GITHUB_APP_ID?: string;
  /** GitHub App private key (PEM, PKCS#1 or PKCS#8). */
  GITHUB_APP_PRIVATE_KEY?: string;
  /** GitHub App OAuth client id / secret (user-to-server tokens). */
  GITHUB_CLIENT_ID?: string;
  GITHUB_CLIENT_SECRET?: string;
  /** 32-byte AES-GCM key, base64, for encrypting GitHub refresh tokens at rest. */
  TOKEN_ENC_KEY?: string;
  /** Owner of template repositories when generating from GitHub templates (optional). */
  GITHUB_TEMPLATE_OWNER?: string;
}

export type HubBindings = Env & HubSecrets;

export interface GitHubAppConfig {
  appId: string;
  privateKey: string;
  clientId: string;
  clientSecret: string;
  slug: string;
}

export type LogLevel = "debug" | "info" | "warn" | "error";

export interface HubConfig {
  /** DEV_MODE=true: DevGitHubAccess, /auth/dev/login, relaxed cookies on http. */
  devMode: boolean;
  /** Public base URL of this Hub, without trailing slash. */
  hubUrl: string;
  /** Studio origin allowed for credentialed CORS. */
  studioOrigin: string;
  /** Real GitHub App credentials, when all are configured. */
  github: GitHubAppConfig | null;
  /** Use the D1-backed GitHub emulation (dev mode or no credentials). */
  useDevGitHub: boolean;
  tokenEncKey: string | null;
  logLevel: LogLevel;
  /** Session cookies get `Secure` when the Hub is served over https. */
  secureCookies: boolean;
}

const trimSlash = (s: string) => s.replace(/\/+$/, "");

export function readConfig(env: HubBindings): HubConfig {
  const devMode = String(env.DEV_MODE ?? "").toLowerCase() === "true";
  const hubUrl = trimSlash(env.HUB_URL || "http://localhost:8787");
  const github =
    env.GITHUB_APP_ID &&
    env.GITHUB_APP_PRIVATE_KEY &&
    env.GITHUB_CLIENT_ID &&
    env.GITHUB_CLIENT_SECRET
      ? {
          appId: env.GITHUB_APP_ID,
          privateKey: env.GITHUB_APP_PRIVATE_KEY,
          clientId: env.GITHUB_CLIENT_ID,
          clientSecret: env.GITHUB_CLIENT_SECRET,
          slug: env.GITHUB_APP_SLUG || "openspace",
        }
      : null;
  const level = (env.LOG_LEVEL || "info").toLowerCase();
  return {
    devMode,
    hubUrl,
    studioOrigin: trimSlash(env.STUDIO_ORIGIN || "http://localhost:5173"),
    github,
    useDevGitHub: devMode || github === null,
    tokenEncKey: env.TOKEN_ENC_KEY || null,
    logLevel: (["debug", "info", "warn", "error"].includes(level) ? level : "info") as LogLevel,
    secureCookies: hubUrl.startsWith("https://"),
  };
}
